import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

const SidebarMenu = ({ module }) => {
  const [openMenus, setOpenMenus] = useState({});
  const navigate = useNavigate();

  const menus = {
    admin: [
      { name: "Dashboard", path: "/admin/dashboard" },
      {
        name: "User Management",
        subMenu: [
          { name: "List Users", path: "/admin/users" },
          { name: "Add User", path: "/admin/users/add" },
          { name: "Roles", path: "/admin/roles" },
          { name: "Permissions", path: "/admin/permissions" },
        ],
      },
      { name: "Journals", path: "/admin/journals" },
      { name: "Settings", path: "/admin/settings" },
    ],
    journal: [
      { name: "Dashboard", path: "/journal" },
      { name: "Articles", path: "/journal/articles" },
      { name: "Reports", path: "/journal/reports" },
    ],
    library: [
      { name: "Dashboard", path: "/library" },
      { name: "Books", path: "/library/books" },
      { name: "Authors", path: "/library/authors" },
    ],
    ebooks: [
      { name: "Dashboard", path: "/ebooks" },
      { name: "All Ebooks", path: "/ebooks/list" },
    ],
    wikipedia: [{ name: "Dashboard", path: "/wikipedia" }],
    repository: [{ name: "Dashboard", path: "/repository" }],
    researchers: [{ name: "Dashboard", path: "/researchers" }],
  };

  const moduleMenu = menus[module] || [];

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/auth/login");
  };

  const toggleMenu = (name) => {
    setOpenMenus((prev) => ({ ...prev, [name]: !prev[name] }));
  };

  return (
    <aside className="main-sidebar sidebar-dark-primary elevation-4">
      <div className="sidebar">
        <nav className="mt-2">
          <ul
            className="nav nav-pills nav-sidebar flex-column"
            data-widget="treeview"
            role="menu"
          >
            {moduleMenu.map((item, index) => (
              <li
                key={index}
                className={`nav-item ${item.subMenu ? "has-treeview" : ""} ${
                  openMenus[item.name] ? "menu-open" : ""
                }`}
              >
                {item.subMenu ? (
                  <>
                    <p
                      className="nav-link"
                      style={{ cursor: "pointer" }}
                      onClick={() => toggleMenu(item.name)}
                    >
                      <span>{item.name}</span>
                      <i className="right fas fa-angle-left"></i>
                    </p>
                    <ul className="nav nav-treeview">
                      {item.subMenu.map((sub, subIdx) => (
                        <li className="nav-item" key={subIdx}>
                          <Link to={sub.path} className="nav-link">
                            <p>{sub.name}</p>
                          </Link>
                        </li>
                      ))}
                    </ul>
                  </>
                ) : (
                  <Link to={item.path} className="nav-link">
                    <p>{item.name}</p>
                  </Link>
                )}
              </li>
            ))}
            <li className="nav-item mt-3">
              <button className="btn btn-danger w-100" onClick={handleLogout}>
                Logout
              </button>
            </li>
          </ul>
        </nav>
      </div>
    </aside>
  );
};

export default SidebarMenu;
